class _FileFormState extends State<FileForm>{late TextEditingController title,type,deal,area,price,address,owner,phone,desc,link,key,token;bool loading=false;String msg='';@override void initState(){super.initState();final x=widget.existing??{};title=TextEditingController(text:'${x['title']??''}');type=TextEditingController(text:'${x['type']??'آپارتمان'}');deal=TextEditingController(text:'${x['deal']??'فروش'}');area=TextEditingController(text:'${x['area']??''}');price=TextEditingController(text:'${x['price']??''}');address=TextEditingController(text:'${x['address']??''}');owner=TextEditingController(text:'${x['ownerName']??''}');phone=TextEditingController(text:'${x['ownerPhone']??''}');desc=TextEditingController(text:'${x['description']??''}');link=TextEditingController(text:'${x['divarLink']??''}');key=TextEditingController();token=TextEditingController();}
String? postToken(){for(final r in [RegExp(r'divar\.ir/v/([A-Za-z0-9_-]{6,20})'),RegExp(r'divar\.ir/[^/]+/[^/]+/([A-Za-z0-9_-]{6,20})')]){final m=r.firstMatch(link.text);if(m!=null)return m.group(1);}return null;}
