Future<void> save()async{final all=await DB.files();final code=widget.existing!=null?'${widget.existing!['code']}':'MM-${DateTime.now().millisecondsSinceEpoch.toString().substring(5)}';final im=await DB.get('images');final x={'code':code,'title':title.text,'type':type.text,'deal':deal.text,'area':area.text,'price':price.text,'address':address.text,'ownerName':owner.text,'ownerPhone':phone.text,'description':desc.text,'divarLink':link.text,'images':im.isEmpty?[]:jsonDecode(im),'updated':DateFormat('yyyy/MM/dd HH:mm').format(DateTime.now())};final i=all.indexWhere((e)=>e['code']==code);if(i>=0)all[i]=x;else all.add(x);await DB.saveFiles(all);if(phone.text.trim().isNotEmpty){final cs=await DB.customers();if(!cs.contains(phone.text.trim())){cs.add(phone.text.trim());await DB.saveCustomers(cs);}}widget.onSaved();if(mounted)Navigator.pop(context);}
